#!/usr/bin/env bash
set -euo pipefail
# Source the selected Go 1.26 toolchain before invoking this script.
: "${MOVIEPILOT_SOURCE:?fixed MoviePilot source checkout required}"
: "${INSTALLED_PLUGIN_SOURCE:?fixed installed plugin source directory required}"
: "${DOWNLOADER_TEST_TOOLS:?20261030 isolated downloader tools directory required}"
RUN_ID=${1:?unique new owned daemon instance name required}
PHASE=${2:-paused}
case "$PHASE" in paused|active) ;; *) echo 'phase must be paused or active' >&2; exit 2;; esac
REPO=$(cd -- "$(dirname -- "$0")/../.." && pwd)
cd "$REPO"
WORK="$REPO/work/transmission-query"
mkdir -p "$WORK/bin" "$WORK/logs" "$WORK/deps"
if ! PYTHONPATH="$WORK/deps" python3 -c 'import transmission_rpc,importlib.metadata;assert importlib.metadata.version("transmission-rpc")=="7.0.11"'; then
  python3 -m pip install --disable-pip-version-check --target "$WORK/deps" 'transmission-rpc==7.0.11'
fi
go build -buildvcs=false -race -o "$WORK/bin/allowed" ./cmd/owned-transmission-query-fixture
go build -buildvcs=false -race -ldflags='-X main.fixtureDenied=true' -o "$WORK/bin/denied" ./cmd/owned-transmission-query-fixture
export OWNED_TRANSMISSION_QUERY_FIXTURE_BINARY="$WORK/bin/allowed"
export OWNED_TRANSMISSION_QUERY_DENIED_FIXTURE_BINARY="$WORK/bin/denied"
export PYTHONPATH="$WORK/deps" TRANSMISSION_QUERY_PHASE="$PHASE"
PATTERN='^(TestTransmissionQuery|TestSharedTransmissionQuery)'
if [[ "$PHASE" == active ]]; then PATTERN='^TestSharedTransmissionQueryReal(SourceWorker|UIHTTP)$'; fi
# Credentials are generated by the harness and inherited only by its child.
# Never copy or commit the harness runtime directory, account files or App DB.
"$DOWNLOADER_TEST_TOOLS/bin/isolated-daemons" run --service transmission --instance "$RUN_ID" -- \
  python3 testdata/shared-transmission-query/source_real.py "$MOVIEPILOT_SOURCE" "$INSTALLED_PLUGIN_SOURCE" "$WORK/$RUN_ID-source.json" \
  go test -race ./internal/plugins ./internal/app -run "$PATTERN" -count=1 -v
